//! Tauri wiring for Machi: window setup, commands and events only (§1.1).
//!
//! All logic lives in `machi-core`; this crate turns it into typed Tauri commands whose
//! TypeScript bindings are generated by tauri-specta into `src/lib/bindings.ts`.

mod commands;

use specta_typescript::Typescript;
use tauri_specta::{Builder, ErrorHandlingMode, collect_commands};

/// Path of the generated bindings, relative to the `src-tauri` crate directory.
pub const BINDINGS_PATH: &str = "../src/lib/bindings.ts";

/// Builds the tauri-specta registry of every command and event exposed to the UI.
pub fn specta_builder() -> Builder<tauri::Wry> {
    Builder::<tauri::Wry>::new()
        .error_handling(ErrorHandlingMode::Result)
        .dangerously_cast_bigints_to_number()
        .commands(collect_commands![commands::platform_info])
}

/// Writes the TypeScript bindings. Used by `cargo run -p machi --example export_bindings`.
pub fn export_bindings(path: &std::path::Path) -> Result<(), String> {
    specta_builder()
        .export(Typescript::default().header("// @ts-nocheck\n/* eslint-disable */\n// Generated by tauri-specta from the Rust command definitions. Do not edit.\n"), path)
        .map_err(|err| err.to_string())
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    let builder = specta_builder();

    let result = tauri::Builder::default()
        .plugin(tauri_plugin_opener::init())
        .invoke_handler(builder.invoke_handler())
        .setup(move |app| {
            builder.mount_events(app);
            Ok(())
        })
        .run(tauri::generate_context!());

    if let Err(err) = result {
        eprintln!("machi failed to start: {err}");
        std::process::exit(1);
    }
}
